#!/usr/bin/env python3
"""Build static Pages website + print PDF from the same original chapter Markdown.
No AI API / web scraping / automatic WeChat publishing.
"""
from __future__ import annotations
from pathlib import Path
import csv, json, html, re, sys
from datetime import date
from urllib.parse import quote
import mistune

ROOT = Path(__file__).resolve().parents[1]
DOCS = ROOT/'docs'
CHAPTERS = ROOT/'content'/'chapters'
SITE_URL = 'https://aipmandy.github.io/wechat-account-launch-handbook/'
SOCIAL_IMAGE = SITE_URL + 'assets/social-preview.png'
PDF_NAME = 'wechat-account-launch-handbook.pdf'
TODAY = '2026-11-15'
md = mistune.create_markdown(escape=True, plugins=['table','strikethrough','url'])
chapters=[]
for file in sorted(CHAPTERS.glob('*.md')):
    s=file.read_text(encoding='utf-8')
    match=re.search(r'^#\s+(.+)$', s, re.M)
    title=match.group(1).strip() if match else file.stem
    plain=re.sub(r'[`*#>\[\]()]',' ',s)
    plain=re.sub(r'\s+',' ',plain).strip()
    chapters.append(dict(slug=file.stem,title=title,raw=s,body=md(s),excerpt=plain[:165]))
assert len(chapters)==24, f'expected 24 chapters, found {len(chapters)}'

