JS=r'''
(()=>{
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const root='/wechat-account-launch-handbook/';
function fmt(n){return Number.isFinite(n)?new Intl.NumberFormat('zh-CN',{maximumFractionDigits:0}).format(n):'—'}
const search=$('#search');if(search){search.addEventListener('input',()=>{const q=search.value.trim().toLowerCase();$$('.chapter-tile').forEach(el=>{el.hidden=!!q&&!((el.dataset.search||'').toLowerCase().includes(q));});const visible=$$('.chapter-tile:not([hidden])').length;$('#search-result').textContent=visible+' / 24 章';});}
const select=$('#route-select');if(select){select.addEventListener('change',()=>{const paths={ads:'先读第 01、03、07、11、12、20 章。重点验证细分读者需求和真实阅读，满足资格后再核对后台广告入口。',brands:'先读第 13–19 章，再回看第 04、07、08 章。先做一篇真实实测作品，之后准备媒体包与小范围品牌对接。',ip:'先读第 01、03、06、08、11、21 章，围绕服务中真实发生的问题提供免费可复用解法，不用泛流量替代高意向线索。'};$('#route-result').textContent=paths[select.value]||'请选择主要路径';});select.dispatchEvent(new Event('change'));}
let vals=[];function score(){const a=$$('.score-input');if(!a.length)return;vals=a.map(x=>+x.value);a.forEach(x=>{const l=$('#num-'+x.id);if(l)l.textContent=x.value});let s=vals.reduce((x,y)=>x+y,0);let evidence=$('#has-evidence').checked;$('#topic-score').innerHTML=fmt(s)+'<span> / 25</span>';$('#topic-decision').textContent=!evidence?'证据门禁未通过：先补一手实测或可靠来源，再考虑发表':s>=20?'可优先安排实测与人工审稿（不是推荐流量保证）':s>=14?'先缩小人群或优化实测产物，然后再评估':'暂缓；说明读者需求、材料和差异化';}$$('.score-input,#has-evidence').forEach(x=>x.addEventListener('input',score));score();
function calculate(){const n=+($('#deals')?.value||0),price=+($('#price')?.value||0),cost=+($('#cost')?.value||0),fixed=+($('#fixed')?.value||0);let revenue=n*price,margin=revenue-n*cost-fixed;$('#projected-revenue').textContent='¥ '+fmt(revenue);$('#projected-margin').textContent='¥ '+fmt(margin);$('#projected-margin').style.color=margin<0?'#a52b2b':'#1746a2';}$$('.calc').forEach(el=>el.addEventListener('input',calculate));if($('#deals'))calculate();
const tasks=$('#tasks');if(tasks){let plan=[];try{plan=JSON.parse($('#sop-data').textContent)}catch(e){}let saved={};try{saved=JSON.parse(localStorage.getItem('wechat_launch_tasks_v1')||'{}')}catch(e){};function rerender(){tasks.innerHTML=plan.map((it,i)=>`<div class="task ${saved[i]?'isdone':''}"><span class="taskday">D${String(i+1).padStart(2,'0')}</span><label><input type="checkbox" data-index="${i}" ${saved[i]?'checked':''}> ${escapeHTML(it.task)}<small>${escapeHTML(it.outcome)}</small></label></div>`).join('');const count=Object.values(saved).filter(Boolean).length;$('#progress-count').textContent=count+' / '+plan.length;$('#progress-bar').style.width=(count/Math.max(1,plan.length)*100)+'%';}function escapeHTML(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}tasks.addEventListener('change',e=>{if(e.target.matches('input[type="checkbox"]')){saved[e.target.dataset.index]=e.target.checked;localStorage.setItem('wechat_launch_tasks_v1',JSON.stringify(saved));rerender();}});rerender();$('#export-sop').addEventListener('click',()=>{let data={project:'公众号起号30天执行',exported:new Date().toISOString(),tasks:plan.map((x,i)=>({...x,done:!!saved[i]}))};let blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='30-day-progress.json';a.click();URL.revokeObjectURL(a.href);});}
$$('.copy').forEach(button=>button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(button.dataset.copy||'AIPMAndy');const out=button.parentElement.querySelector('.msg');if(out)out.textContent='已复制';}catch(e){const out=button.parentElement.querySelector('.msg');if(out)out.textContent='复制失败，请手动选择：'+(button.dataset.copy||'AIPMAndy');}}));
})();
'''
